 return f'''<a class="skip" href="#main">본문으로 바로가기</a><header class="site-header"><div class="nav-wrap"><a class="brand" href="{prefix}index.html" aria-label="이승열 포트폴리오 홈"><span class="brand-mark">SY<span>.</span></span><span>이승열 <small>PORTFOLIO</small></span></a><button class="menu-toggle" aria-label="메뉴 열기" aria-expanded="false" aria-controls="main-nav"><span></span><span></span></button><nav id="main-nav" aria-label="주 메뉴"><a href="{prefix}index.html#skills">Skills</a><a href="{prefix}index.html#projects">Projects</a><a href="{prefix}index.html#about">About</a><a href="{prefix}index.html#contact">Contact</a><a href="https://github.com/lsy49055089" target="_blank" rel="noopener noreferrer">GitHub ↗</a></nav><a class="print-link" href="{prefix}print.html" target="_blank" rel="noopener">PDF로 저장 <span>↓</span></a></div></header>'''
