def head(title,desc,prefix=''):
 return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#171918"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}style.css"></head><body>'''

def card(p,n):
 image=f'<img src="assets/{p["image"]}" alt="{e(p["alt"])}" loading="lazy" width="800" height="450">' if p['image'] else ('<div class="logic-art" aria-hidden="true"><span class="logic-tag">'+('UVM ENVIRONMENT' if p['kind']=='verification' else 'AXI4-LITE SYSTEM')+'</span><div class="logic-path">'+('Sequence <b>→</b> Driver <b>→</b> DUT' if p['kind']=='verification' else 'MicroBlaze <b>→</b> AXI Interconnect')+'</div><div class="logic-bus"></div><div class="logic-blocks">'+('<span>Monitor</span><span>Scoreboard</span><span>Coverage</span>' if p['kind']=='verification' else '<span>GPIO</span><span>Timer</span><span>UART</span><span>SPI</span><span>I2C</span>')+'</div><span class="logic-note">'+('Expected / Observed · PASS / FAIL' if p['kind']=='verification' else 'Custom IP · Register Map · MMIO')+'</span></div>')
 return f'''<article class="project-card" data-category="{p['kind']}"><a class="project-image {p['id']}" href="projects/{p['id']}.html" aria-label="{e(p['title'])} 상세">{image}<span class="image-arrow">↗</span></a><div class="card-copy"><p class="eyebrow">{n:02d} / {e(p['kicker'])}</p><h3><a href="projects/{p['id']}.html">{e(p['title'])}</a></h3><p class="card-summary">{e(p['summary'])}</p><div class="role"><span>MY ROLE</span><p>{e(p['role'])}</p></div>{tags(p)}<p class="card-result">{e(p['result'])}</p><div class="card-bottom"><span>{e(p['period'])}</span><a href="projects/{p['id']}.html">프로젝트 상세 ↗</a></div></div></article>'''

